file.content:
        # DELETE /v1/trust/allowlist/{source}
        source = unquote(path[len("/v1/trust/allowlist/") :])
        status, body = service.remove_allowlist_entry(source)
        self._send_json(status, body)
    else:
        self._send_json(404, {"error": "not found"})

def do_GET(self) -> None:  # noqa: N802 (stdlib naming)
    path, _, query = self.path.partition("?")
    # Bearer gate first; a failed gate has no side effects.
    if not self._history_authorized("GET", path):
        return
    if path == "/v1/history/trust":
        # GET /v1/history/trust — the contract-ordered
        # {root, records, head} signer log.
        status, body = service.read_history_trust()
        self._send_json(status, body, sort_keys=False)
    elif path.startswith("/v1/transactions/"):
        # GET /v1/transactions/{tx_id} — a transaction receipt; a
        # malformed or unknown tx_id returns 404.
        tx_id = unquote(path[len("/v1/transactions/") :])
        if not tx_id:
            self._send_json(404, {"error": "transaction not found"})
            return
        status, body = service.get_transaction(tx_id)
        self._send_json(status, body)
    elif path == "/v1/trust":
        # The trust document has a contract-fixed key order
        # (genesis_hash, sources, allowlist, audit_signers,
        # source_key_history), so it is serialized in insertion order
        # rather than alphabetically.
        status, body = service.get_trust_document()
        self._send_json(status, body, sort_keys=False)
    elif path == "/v1/audit/events":
        # GET /v1/audit/events?source=&kind=&cursor=&limit=
        params = {
            key: values[0]
            for key, values in parse_qs(query, keep_blank_values=True).items()
        }
        status, body = service.list_audit_events(params)
        self._send_json(status, body)
    elif path == "/v1/audit/export":
        # GET /v1/audit/export?cursor=&limit= — hash-anchored export
        # pages for offline audit verification. Repeated query
        # parameters are rejected 400 like the other strict endpoints.
        parsed = parse_qs(query, keep_blank_values=True)
        if any(len(values) > 1 for values in parsed.values()):
            self._send_json(
                400, {"error": "query parameters must not be repeated"}
            )
            return
        params = {key: values[0] for key, values in parsed.items()}
        status, body = service.export_audit_events(params)
        self._send_json(status, body)
    elif path == "/v1/chain/range":
        # GET /v1/chain/range?after_height=&after_hash=&limit=
        # Incremental canonical-chain page after an anchor. Repeated
        # query parameters are rejected 400 like the strict endpoints.
        parsed = parse_qs(query, keep_blank_values=True)
        if any(len(values) > 1 for values in parsed.values()):
            self._send_json(
                400, {"error": "query parameters must not be repeated"}
            )
            return
        params = {key: values[0] for key, values in parsed.items()}
        status, body = service.get_chain_range(params)
        self._send_json(status, body)
    elif path == "/v1/chain/headers":
        # GET /v1/chain/headers?after_height=&after_hash=&limit= —
        # one signed page of block headers strictly after an anchor;
        # the parameter rules are identical to /v1/chain/range.
        # Repeated query parameters are rejected 400 like the other
        # strict endpoints. The success document has a contract-fixed
        # key order (anchor, headers, tip, auth), so it is serialized
        # in insertion order rather than alphabetically.
        parsed = parse_qs(query, keep_blank_values=True)
        if any(len(values) > 1 for values in parsed.values()):
            self._send_json(
                400, {"error": "query parameters must not be repeated"}
            )
            return
        params = {key: values[0] for key, values in parsed.items()}
        status, body = service.get_chain_headers(params)
        self._send_json(status, body, sort_keys=False)
    elif path == "/v1/chain/finality":
        # GET /v1/chain/finality — the signed finality credential.
        # The endpoint takes no parameters: any query parameter
        # (including a blank one) is rejected 400; a bare trailing
        # "?" carries none and is accepted like the other strict
        # endpoints. The success document has a contract-fixed key
        # order (finalized, tip, auth), so it is serialized in
        # insertion order rather than alphabetically.
        if parse_qs(query, keep_blank_values=True):
            self._send_json(
                400, {"error": "finality endpoint takes no parameters"}
            )
            return
        status, body = service.get_chain_finality()
        self._send_json(status, body, sort_keys=False)
    elif path == "/v1/chain/finalities":
        # GET /v1/chain/finalities?after_height=&after_hash=&limit= —
        # one signed page of finality credentials strictly after an
        # anchor; the parameter rules are identical to
        # /v1/chain/headers (repeated query parameters are rejected
        # 400 like the other strict endpoints). The success document
        # has a contract-fixed key order (anchor, finalities, next,
        # head), so it is serialized in insertion order rather than
        # alphabetically.
        parsed = parse_qs(query, keep_blank_values=True)
        if any(len(values) > 1 for values in parsed.values()):
            self._send_json(
                400, {"error": "query parameters must not be repeated"}
            )
            return
        params = {key: values[0] for key, values in parsed.items()}
        status, body = service.get_chain_finalities(params)
        self._send_json(status, body, sort_keys=False)
    elif path == "/v1/chain":
        status, body = service.get_chain()
        self._send_json(status, body)

def get_transaction(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id} — one transaction receipt.

    The lookup covers the canonical chain and the mempool only; candidate
    forks are never exposed. A ``tx_id`` that is not exactly 64 lowercase
    hex characters, or one nothing holds, returns 404.

    A mempool transaction is reported ``pending`` with ``height``,
    ``block_hash`` and ``index`` all null. A transaction packed into the
    unconfirmed tip block is ``pending`` too, anchored at that block with
    its 0-based in-block index. A transaction in a confirmed block is
    ``confirmed``. Every receipt is built from the stored signed
    transaction: the id is recomputed from its canonical message (never
    taken from an index or a fork-side cache) and the fields are strictly
    re-typed (non-empty strings, a positive non-boolean integer amount),
    so adoption, rollback and restart can only ever surface the current
    canonical/pending state.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        # Canonical chain first: confirmed blocks, then at most one
        # pending tip. The stored signed transaction is the sole source
        # for the receipt, and its id is recomputed rather than trusted
        # from any lookup key.
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id != tx_id:
                    continue
                if not self._is_receipt_tx_well_typed(tx):
                    return 404, {"error": "transaction not found"}
                status = (
                    STATUS_CONFIRMED
                    if block.status == STATUS_CONFIRMED
                    else STATUS_PENDING
                )
                return 200, self._transaction_receipt(
                    tx, status, block.height, block.block_hash, index
                )
        # Still unpacked in the mempool.
        tx = self.store.pending.get(tx_id)
        if tx is not None:
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
            return 200, self._transaction_receipt(
                tx, STATUS_PENDING, None, None, None
            )
        return 404, {"error": "transaction not found"}

@staticmethod
def _is_receipt_tx_well_typed(tx: Transaction) -> bool:
    """Strict receipt-time type check of a stored signed transaction.

    Every stored transaction already passed these checks at submission
    (and again during snapshot recovery); the re-check guarantees a
    receipt can never serialize a value that violates the response
    contract, even if an in-memory invariant were broken.
    """
    return (
        isinstance(tx.sender, str)
        and bool(tx.sender)
        and isinstance(tx.recipient, str)
        and bool(tx.recipient)
        and isinstance(tx.amount, int)
        and not isinstance(tx.amount, bool)
        and tx.amount > 0
        and isinstance(tx.signature, str)
        and bool(tx.signature)
    )

@staticmethod
def _transaction_receipt(
    tx: Transaction,
    status: str,
    height: int | None,
    block_hash: str | None,
    index: int | None,
) -> dict:
    """The fixed nine-field receipt shape."""
    return {
        "tx_id": tx.tx_id,
        "from": tx.sender,
        "to": tx.recipient,
        "amount": tx.amount,
        "signature": tx.signature,
        "status": status,
        "height": height,
        "block_hash": block_hash,
        "index": index,
    }

# -- blocks -------------------------------------------------------------

def mine_block(self) -> tuple[int, dict]:
    """Pack all pending transactions (ascending tx_id) into a pending block.

    Only allowed when the chain tip is confirmed; the new block becomes
    the pending tip until it is confirmed or rolled back.
    """
    with self.store.lock:
        if self.store.tip_is_pending():
            return 409, {"error": "tip block is pending confirmation"}
        if not self.store.pending:
            return 409, {"error": "no pending transactions"}
        ordered = sorted(self.store.pending.values(), key=lambda tx: tx.tx_id)
        block = Block.create(
            height=self.store.next_height(),
            prev_hash=self.store.tip_hash(),
            transactions=ordered,
            status=STATUS_PENDING,
        )
        self.store.chain.append(block)
        removed = [self.store.pending.pop(tx.tx_id) for tx in ordered]
        try:
            self.store.save()
        except BaseException:
            # Undo the in-memory block so nothing un-persisted is visible.
            self.store.chain.pop()
            self.store.pending.update({tx.tx_id: tx for tx in removed})
            raise

def get_chain_headers(self, params: dict) -> tuple[int, dict]:
    """GET /v1/chain/headers — one signed page of block headers.

    Query parameters follow exactly the same rules as
    ``GET /v1/chain/range``: ``after_height`` and ``after_hash`` are both
    required, ``limit`` defaults to 100 and must be a decimal between 1
    and 500; malformed values or unknown parameters are 400, an unknown
    anchor height is 404 and an anchor hash mismatch is 409.

    The success body has the fixed key order ``anchor, headers, tip,
    auth``: ``anchor`` is ``{height, block_hash}`` (the block the page
    starts *after*), ``headers`` are the headers strictly after it in
    ascending height with item key order
    ``height, prev_hash, merkle_root, block_hash, status`` (no
    transactions; a pending chain tip is exported as the page tail),
    ``tip`` is the current chain descriptor S, and ``auth`` is
    ``{key_version, signature}`` — an Ed25519 signature made with the
    current audit signer over
    ``SHA256(UTF8("ledger-headers-v1") || canonical_json({anchor, headers,
    tip}))``. When the anchor is the current tip the page carries an
    empty ``headers`` list, still signed.
    """
    after_height_raw = params.get("after_height")
    after_hash = params.get("after_hash")
    if after_height_raw is None:
        return 400, {"error": "missing parameter: after_height"}
    if after_hash is None:
        return 400, {"error": "missing parameter: after_hash"}
    after_height = _parse_decimal(after_height_raw)
    if after_height is None:
        return 400, {"error": "after_height must be a non-negative decimal"}
    if not crypto.is_hex64(after_hash):
        return 400, {"error": "after_hash must be 64 lowercase hex characters"}
    limit = self.RANGE_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.RANGE_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 500"}
        limit = parsed

    from . import light_client

    with self.store.lock:
        anchor_block = self.store.block_at(after_height)
        if anchor_block is None:
            return 404, {"error": "anchor block not found"}
        if after_hash != anchor_block.block_hash:
            return 409, {
                "error": "after_hash does not match the block at after_height"
            }
        page = self.store.chain[
            after_height + 1 : after_height + 1 + limit
        ]
        anchor = self._anchor_descriptor(anchor_block)
        headers = [self._header_entry(block) for block in page]
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError("no audit signer available for header page")
        auth = light_client.sign_header_page(
            signer["private_key"], signer["version"], anchor, headers, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "anchor": anchor,
            "headers": headers,
            "tip": tip,
            "auth": auth,
        }

def locate_header_fork(self, payload: object) -> tuple[int, dict]:
    """POST /v1/chain/headers/locate — fork location by block locators.

    The request body is a JSON object with the ordered keys ``locators``
    and the optional ``limit``: ``locators`` is an array of 1-64
    ``{height, block_hash}`` items (item key order ``height, block_hash``),
    each height a non-boolean non-negative integer, strictly descending
    and unique across the array, and each hash 64 lowercase hexadecimal
    characters; ``limit`` is a non-boolean integer between 1 and 500 and
    defaults to 100. Every parse or key/value defect is a 400 answered
    before any state is read (no side effects).

    The locators are probed in their supplied order and the first item at
    the same height with the same hash as a main-chain block anchors the
    response; when no locator names a main-chain block the answer is 409.
    On success the body is the same fixed-order signed header page as
    :meth:`get_chain_headers` — ``anchor, headers, tip, auth`` — with the
    headers ascending strictly after the matched anchor (at most
    ``limit`` items; an empty page is signed when the anchor is the tip).
    The main chain and the audit signer are snapshotted together under one
    store lock so the descriptor, the page and the signature can never mix
    states.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    keys = tuple(payload.keys())
    if keys not in (("locators",), ("locators", "limit")):
        return 400, {
            "error": "body must contain only ordered keys locators, limit"
        }
    raw_locators = payload["locators"]
    if not isinstance(raw_locators, list) or not (
        1 <= len(raw_locators) <= 64
    ):
        return 400, {
            "error": "field 'locators' must be an array of 1 to 64 items"
        }
    locators: list[dict] = []
    previous_height: int | None = None
    for item in raw_locators:
        if not isinstance(item, dict) or tuple(item.keys()) != (
            "height",
            "block_hash",
        ):
            return 400, {
                "error": "every locator must be an object with ordered "
                "keys height, block_hash"
            }
        height = item["height"]
        block_hash = item["block_hash"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return 400, {
                "error": "locator height must be a non-negative integer"
            }
        if not crypto.is_hex64(block_hash):
            return 400, {
                "error": "locator block_hash must be 64 lowercase hex characters"
            }
        if previous_height is not None and height >= previous_height:
            return 400, {
                "error": "locator heights must be strictly descending and unique"
            }
        previous_height = height
        locators.append({"height": height, "block_hash": block_hash})
    limit = self.RANGE_DEFAULT_LIMIT
    if "limit" in payload:
        raw_limit = payload["limit"]
        if (
            isinstance(raw_limit, bool)
            or not isinstance(raw_limit, int)
            or not 1 <= raw_limit <= self.RANGE_MAX_LIMIT
        ):
            return 400, {"error": "limit must be an integer between 1 and 500"}
        limit = raw_limit

    from . import light_client

    with self.store.lock:
        anchor_block = None
        for locator in locators:
            candidate = self.store.block_at(locator["height"])
            if (
                candidate is not None
                and candidate.block_hash == locator["block_hash"]
            ):
                anchor_block = candidate
                break
        if anchor_block is None:
            return 409, {"error": "no locator matches a main-chain block"}
        anchor_height = anchor_block.height
        page = self.store.chain[
            anchor_height + 1 : anchor_height + 1 + limit
        ]
        anchor = self._anchor_descriptor(anchor_block)
        headers = [self._header_entry(block) for block in page]
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot carries a current audit signer after
            # recovery; reaching here is a programming error.
            raise RuntimeError("no audit signer available for header page")
        auth = light_client.sign_header_page(
            signer["private_key"], signer["version"], anchor, headers, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "anchor": anchor,
            "headers": headers,
            "tip": tip,
            "auth": auth,
        }

# -- signed finality credential ------------------------------------------

def get_chain_finality(self) -> tuple[int, dict]:
    """GET /v1/chain/finality — the signed irreversible finality credential.

    The endpoint takes no query parameters (the HTTP layer rejects any
    with 400). Under one store lock the main chain and the current audit
    signer are snapshotted together. The success body has the fixed key
    order ``finalized, tip, auth``: ``finalized`` is
    ``{height, block_hash}`` naming the last **confirmed** canonical
    block (the genesis block is born confirmed), ``tip`` is the current
    chain descriptor S (identical to ``GET /v1/chain/headers``'s
    ``tip``) and ``auth`` is ``{key_version, signature}`` — an Ed25519
    signature made with the current audit signer over
    ``SHA256(UTF8("ledger-finality-v1") || canonical_json({finalized,
    tip}))``. A pending chain tip is reported in ``tip`` but never
    advances ``finalized``.
    """
    from . import light_client

    with self.store.lock:
        finalized_block = next(
            block
            for block in reversed(self.store.chain)
            if block.status == STATUS_CONFIRMED
        )
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError("no audit signer available for finality")
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "finalized": finalized,
            "tip": tip,
            "auth": auth,
        }

# -- paginated finality credentials ---------------------------------------

@staticmethod
def _block_descriptor(block: Block) -> dict:
    """The chain descriptor S of the prefix ending at ``block``."""
    return {
        "tip_hash": block.block_hash,
        "height": block.height,
        # The length counts every block including the genesis block.
        "length": block.height + 1,
        "status": block.status,
    }

def get_chain_finalities(self, params: dict) -> tuple[int, dict]:
    """GET /v1/chain/finalities — one signed page of finality credentials.

    Query parameters follow exactly the same rules as
    ``GET /v1/chain/headers``: ``after_height`` and ``after_hash`` are
    both required, ``limit`` defaults to 100 and must be a decimal
    between 1 and 500; malformed values or unknown parameters are 400
    (a repeated parameter is rejected by the HTTP layer), an unknown
    anchor height is 404 and an anchor hash mismatch — or a pending
    anchor — is 409. Every failure is answered before any state
    changes (the endpoint is read-only).

    The success body has the fixed key order ``anchor, finalities,
    next, head``: ``anchor`` is ``{height, block_hash}`` naming exactly
    the requested anchor block; ``finalities`` carries at most
    ``limit`` credentials for the consecutive **confirmed** blocks
    strictly after the anchor in ascending height, each in the exact
    ``GET /v1/chain/finality`` shape (key order ``finalized, tip,
    auth``, the ``ledger-finality-v1`` signature) with ``finalized``
    naming that block and ``tip`` the chain descriptor S of the prefix
    ending at it; ``head`` is the current finality credential
    (identical to ``GET /v1/chain/finality``). ``next`` is the page's
    last ``finalized`` — ready to be resubmitted as the next anchor —
    or ``null`` when the page already reaches the finalized head (an
    anchor that *is* the head yields an empty page and ``null``). The
    chain, the current audit signer and the whole response are
    snapshotted under one store lock, and a signing or construction
    failure raises instead of returning a partial page.
    """
    if any(key not in ("after_height", "after_hash", "limit") for key in params):
        return 400, {"error": "unknown query parameter"}
    after_height_raw = params.get("after_height")
    after_hash = params.get("after_hash")
    if after_height_raw is None:
        return 400, {"error": "missing parameter: after_height"}

def get_proof(self, height: object, tx_id: object) -> tuple[int, dict]:
    """Return a Merkle inclusion proof for tx_id at the given height.

    Returns 404 for an unknown height, a malformed height/tx_id, or a
    transaction absent from that block. Proofs are only issued for
    confirmed blocks; a pending block returns 409.
    """
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block is pending confirmation"}
        tx_ids = [tx.tx_id for tx in block.transactions]
        try:
            index = tx_ids.index(tx_id)
        except ValueError:
            return 404, {"error": "transaction not found"}
        siblings = crypto.merkle_proof(tx_ids, index)
        return 200, {
            "height": block.height,
            "tx_id": tx_id,
            "index": index,
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "siblings": siblings,
        }

def get_proofs(self, height: object, payload: object) -> tuple[int, dict]:
    """Return Merkle inclusion proofs for a batch of tx_ids at one height.

    POST /v1/blocks/{height}/proofs with ``{"tx_ids": [...]}``. The body
    must be a JSON object containing exactly the ``tx_ids`` key: a
    non-empty list of distinct 64-lowercase-hex strings. A malformed body
    — parse failure, missing/extra keys, a wrong type, an empty list,
    duplicates or a wrongly formatted id — is 400 and never touches state.
    A malformed/unknown height or any requested transaction absent from
    the block is 404; proofs are only issued for confirmed blocks, so a
    pending block returns 409.

    On success the body carries the block's complete ascending
    ``transaction_ids`` (every leaf) plus one
    ``{tx_id, index, siblings}`` proof per requested id, the proofs sorted
    by tx_id; the sibling paths run leaf-to-root exactly like
    :meth:`get_proof`.
    """
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return 400, {"error": "request body must be a JSON object with only 'tx_ids'"}
    tx_ids_raw = payload["tx_ids"]
    if not isinstance(tx_ids_raw, list) or not tx_ids_raw:
        return 400, {"error": "field 'tx_ids' must be a non-empty array"}
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids_raw):
        return 400, {
            "error": "every tx_id must be a string of 64 lowercase hex characters"
        }
    if len(set(tx_ids_raw)) != len(tx_ids_raw):
        return 400, {"error": "tx_ids must be distinct"}

    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block is pending confirmation"}
        tx_ids = [tx.tx_id for tx in block.transactions]
        present = set(tx_ids)
        if any(tx_id not in present for tx_id in tx_ids_raw):
            return 404, {"error": "transaction not found"}
        requested = sorted(set(tx_ids_raw))
        proofs = []
        for tx_id in requested:
            index = tx_ids.index(tx_id)
            proofs.append({
                "tx_id": tx_id,
                "index": index,
                "siblings": crypto.merkle_proof(tx_ids, index),
            })
        return 200, {
            "height": block.height,
            "block_hash": block.block_hash,
            "merkle_root": block.merkle_root,
            "transaction_ids": tx_ids,
            "proofs": proofs,
        }

# -- accounts -----------------------------------------------------------

def get_account(self, account: str) -> tuple[int, dict]:
    with self.store.lock:
        entry = self.store.accounts.get(account)
        if entry is None:
            return 404, {"error": "account not found"}

        body = self._fork_summary(fork)
        body["blocks"] = [block.to_dict() for block in fork]
        return 200, body

# -- incremental chain ranges --------------------------------------------

RANGE_DEFAULT_LIMIT = 100
RANGE_MAX_LIMIT = 500

@staticmethod
def _anchor_descriptor(block: Block) -> dict:
    """Public range anchor shape: {height, block_hash}."""
    return {"height": block.height, "block_hash": block.block_hash}

def get_chain_range(self, params: dict) -> tuple[int, dict]:
    """GET /v1/chain/range — the canonical blocks strictly after an anchor.

    Query parameters: ``after_height`` (a non-negative decimal anchor
    height) and ``after_hash`` (the anchor block's hash, 64 lowercase hex
    characters), both required, plus ``limit`` (default 100, range 1-500).
    Every value must follow the strict decimal/hex format used by the
    other query endpoints; a repeated parameter is rejected by the HTTP
    layer.

    Returns, under the store lock,
    ``{anchor, blocks, canonical, next_height}``: ``anchor`` is
    ``{height, block_hash}`` naming the block the page starts *after*;
    ``blocks`` are the complete blocks following it (full documents
    including transactions; a pending tip block is exported too), up to
    ``limit``; ``canonical`` is the current chain descriptor S;
    ``next_height`` is the height immediately after the returned page, or
    ``null`` when the page already ends at the chain tip. A well-formed
    but unknown anchor height returns 404; a malformed anchor hash returns
    400; an anchor hash that does not match the block at that height
    returns 409.
    """
    after_height_raw = params.get("after_height")
    after_hash = params.get("after_hash")
    if after_height_raw is None:
        return 400, {"error": "missing parameter: after_height"}
    if after_hash is None:
        return 400, {"error": "missing parameter: after_hash"}
    after_height = _parse_decimal(after_height_raw)
    if after_height is None:
        return 400, {"error": "after_height must be a non-negative decimal"}
    if not crypto.is_hex64(after_hash):
        return 400, {"error": "after_hash must be 64 lowercase hex characters"}
    limit = self.RANGE_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.RANGE_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 500"}
        limit = parsed

    with self.store.lock:
        anchor_block = self.store.block_at(after_height)
        if anchor_block is None:
            return 404, {"error": "anchor block not found"}
        if after_hash is not None and after_hash != anchor_block.block_hash:
            return 409, {
                "error": "after_hash does not match the block at after_height"
            }
        page = self.store.chain[
            after_height + 1 : after_height + 1 + limit
        ]
        page_end_height = page[-1].height if page else anchor_block.height
        if page_end_height < self.store.chain[-1].height:
            next_height = page_end_height + 1
        else:
            next_height = None
        return 200, {
            "anchor": self._anchor_descriptor(anchor_block),
            "blocks": [block.to_dict() for block in page],
            "canonical": self._fork_summary(self.store.chain),
            "next_height": next_height,
        }

